import{_ as e,o as a,c as n,ah as s}from"./chunks/framework.sPHStHqt.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/architecture.md","filePath":"getting-started/architecture.md","lastUpdated":1789630599000}'),o={name:"getting-started/architecture.md"};function r(i,t,d,h,l,c){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>You don&#39;t need to be a developer to run the platform, but understanding how it keeps tenants apart makes everything else — plans, custom domains, the cross-tenant views — make sense. This page explains the model in plain terms.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How one installation serves many tenants</li><li>How each tenant&#39;s data stays private</li><li>How the super admin sees across all tenants</li></ul></div><h2 id="one-platform-many-tenants" tabindex="-1">One platform, many tenants <a class="header-anchor" href="#one-platform-many-tenants" aria-label="Permalink to &quot;One platform, many tenants&quot;">​</a></h2><p>There is a single Krayin installation. Every business on it is a <strong>tenant</strong> (internally, a &quot;company&quot;), and every tenant shares that one installation — you don&#39;t run a separate copy of Krayin per customer.</p><p>What makes each tenant feel like they have their own CRM is two things: a web address of their own, and strict data separation.</p><h2 id="addresses-subdomains-and-custom-domains" tabindex="-1">Addresses: subdomains and custom domains <a class="header-anchor" href="#addresses-subdomains-and-custom-domains" aria-label="Permalink to &quot;Addresses: subdomains and custom domains&quot;">​</a></h2><p>Each tenant is reached at their own <strong>subdomain</strong> — <code>acme.yourplatform.com</code>, <code>northwind.yourplatform.com</code>, and so on. The subdomain is the tenant&#39;s <strong>username</strong>, chosen when they register. The platform reads the address on every request and serves that tenant&#39;s CRM.</p><p>A tenant can also point their <strong>own domain</strong> at the platform — <code>crm.acmeconsulting.com</code> instead of <code>acme.yourplatform.com</code>. That&#39;s covered on <a href="/tenants/custom-domains">Custom Domains</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This is why usernames must be unique and URL-safe: the username <em>is</em> the address. Two tenants can&#39;t share one, just as two websites can&#39;t share a domain.</p></div><h2 id="data-separation-how-tenants-stay-private" tabindex="-1">Data separation: how tenants stay private <a class="header-anchor" href="#data-separation-how-tenants-stay-private" aria-label="Permalink to &quot;Data separation: how tenants stay private&quot;">​</a></h2><p>All tenants&#39; data lives in one shared database, but each record is stamped with the tenant it belongs to. When someone is signed in to a tenant&#39;s CRM, the platform automatically limits <strong>every</strong> query to that tenant&#39;s own records — a tenant simply cannot see, or reach, another tenant&#39;s leads, contacts or quotes. The separation is enforced for them at the data layer, so there&#39;s nothing a tenant can do to step outside their own CRM.</p><p>A handful of genuinely shared reference tables — the list of countries and states, and the directory of tenants itself — sit outside this scoping, because they&#39;re common to everyone.</p><div class="tip custom-block"><p class="custom-block-title">Another way to separate tenants</p><p>This is the <strong>single-database</strong> edition, where separation is enforced in software. Krayin also offers a <strong>multi-database</strong> edition that gives each tenant a database of its own — see <a href="/getting-started/multi-database">Multi-Database</a> for how the two compare.</p></div><h2 id="the-super-admin-sees-everything" tabindex="-1">The super admin sees everything <a class="header-anchor" href="#the-super-admin-sees-everything" aria-label="Permalink to &quot;The super admin sees everything&quot;">​</a></h2><p>You, signed in to the super-admin panel, are the exception. The per-tenant limit doesn&#39;t apply to you: that&#39;s precisely why you can see <strong>all</strong> tenants on the <a href="/super-admin/dashboard">dashboard</a>, and browse <a href="/super-admin/leads">Leads</a> and <a href="/super-admin/quotes">Quotes</a> from every tenant in one list.</p><p>So there are two vantage points, by design:</p><table tabindex="0"><thead><tr><th></th><th>A tenant&#39;s admin</th><th>The super admin</th></tr></thead><tbody><tr><td>Signs in at</td><td><code>tenant.yourplatform.com/admin/login</code></td><td><code>yourplatform.com/super/login</code></td></tr><tr><td>Sees</td><td>Only their own CRM</td><td>Every tenant</td></tr><tr><td>Manages</td><td>Their leads, quotes, contacts, team</td><td>Tenants, plans, subscriptions, invoices</td></tr></tbody></table><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Stand the platform up → <a href="/getting-started/installation">Installation</a></li><li>See the operator&#39;s view of all tenants → <a href="/super-admin/tenant-management">Tenant Management</a></li><li>Set a tenant up on their own domain → <a href="/tenants/custom-domains">Custom Domains</a></li></ul>',20)])])}const u=e(o,[["render",r]]);export{p as __pageData,u as default};
